import copy
import os
import sys
from importlib import import_module
from importlib.util import find_spec as importlib_find


def cached_import(module_path):
    # Check whether module is loaded and fully initialized.
    if not (
        (module := sys.modules.get(module_path))
        and (spec := getattr(module, "__spec__", None))
        and getattr(spec, "_initializing", False) is False
    ):
        module = import_module(module_path)
    return module


def import_string(dotted_path):
    """
    Import a dotted module path and return the module or attribute/class
    designated by the path. Raise ImportError if the import failed.
    """
    if "." not in dotted_path:
        return cached_import(dotted_path)
    else:
        # Force a consistent state by eagerly importing the entire dotted path.
        try:
            cached_import(dotted_path)
        except ImportError:
            pass

        module_path, class_name = dotted_path.rsplit(".", 1)
        module = cached_import(module_path)

        # Attempt getattr first, which will return any named objects
        # in a loaded module or a previously loaded submodule.
        try:
            import_target = getattr(module, class_name)
        except AttributeError:
            try:
                import_target = cached_import(dotted_path)
            except ImportError as err:
                raise ImportError(
                    'Module "%s" does not define a "%s" attribute/class'
                    % (module_path, class_name)
                ) from err
        return import_target


def autodiscover_modules(*args, **kwargs):
    """
    Auto-discover INSTALLED_APPS modules and fail silently when
    not present. This forces an import on them to register any admin bits they
    may want.

    You may provide a register_to keyword parameter as a way to access a
    registry. This register_to object must have a _registry instance variable
    to access it.
    """
    from django.apps import apps

    register_to = kwargs.get("register_to")
    for app_config in apps.get_app_configs():
        for module_to_search in args:
            # Attempt to import the app's module.
            try:
                if register_to:
                    before_import_registry = copy.copy(register_to._registry)

                import_module("%s.%s" % (app_config.name, module_to_search))
            except Exception:
                # Reset the registry to the state before the last import
                # as this import will have to reoccur on the next request and
                # this could raise NotRegistered and AlreadyRegistered
                # exceptions (see #8245).
                if register_to:
                    register_to._registry = before_import_registry

                # Decide whether to bubble up this error. If the app just
                # doesn't have the module in question, we can ignore the error
                # attempting to import it, otherwise we want it to bubble up.
                if module_has_submodule(app_config.module, module_to_search):
                    raise


def module_has_submodule(package, module_name):
    """See if 'module' is in 'package'."""
    try:
        package_name = package.__name__
        package_path = package.__path__
    except AttributeError:
        # package isn't a package.
        return False

    full_module_name = package_name + "." + module_name
    try:
        return importlib_find(full_module_name, package_path) is not None
    except ModuleNotFoundError:
        # When module_name is an invalid dotted path, Python raises
        # ModuleNotFoundError.
        return False


def module_dir(module):
    """
    Find the name of the directory that contains a module, if possible.

    Raise ValueError otherwise, e.g. for namespace packages that are split
    over several directories.
    """
    # Convert to list because __path__ may not support indexing.
    paths = list(getattr(module, "__path__", []))
    if len(paths) == 1:
        return paths[0]
    else:
        filename = getattr(module, "__file__", None)
        if filename is not None:
            return os.path.dirname(filename)
    raise ValueError("Cannot determine directory containing %s" % module)


def qualname(value):
    """
    Return the fully qualified name (dotted module path) for a class, function,
    or type (e.g. 'django.db.models.Model').
    """
    if getattr(value, "__self__", None) and isinstance(value.__self__, type):
        klass = value.__self__
        module = getattr(klass, "__module__", None)
        if not module:
            raise ValueError(
                f"Cannot determine module path for {value!r}: "
                f"{klass!r} has no __module__."
            )
        return f"{module}.{klass.__qualname__}.{value.__name__}"

    if not hasattr(value, "__module__") or value.__module__ is None:
        raise ValueError(
            f"Cannot determine module path for {value!r}: no __module__ attribute."
        )
    if not hasattr(value, "__qualname__"):
        raise ValueError(
            f"Cannot determine module path for {value!r}: no __qualname__ attribute."
        )
    if "<" in value.__qualname__:
        raise ValueError(
            f"Cannot determine module path for {value!r}: local or anonymous object."
        )

    return f"{value.__module__}.{value.__qualname__}"

